const db = require("../config/db");

/**
 * Idempotent startup migration for the admin block-plan registry.
 *
 * `subdivision_lots` holds the exact per-lot coordinates an admin imports from
 * the City's block plans. It is what lets the owner location pin land on the
 * real Blk/Lot instead of the deterministic grid fallback in geocode.js.
 *
 * Runs on both engines (unlike the legacy MySQL-only ensure* helpers in
 * server.js), because the live database is PostgreSQL/Supabase and has no
 * separate migration runner:
 *   - PostgreSQL: double precision + GENERATED BY DEFAULT AS IDENTITY
 *   - MySQL:      DOUBLE + AUTO_INCREMENT
 */
async function ensureSubdivisionLots() {
  try {
    if (db.dialect === "postgres") {
      await db.query(`
        CREATE TABLE IF NOT EXISTS subdivision_lots (
          id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
          subdivision_key varchar(150) NOT NULL,
          block varchar(30) NOT NULL DEFAULT '',
          lot varchar(30) NOT NULL DEFAULT '',
          latitude double precision NOT NULL,
          longitude double precision NOT NULL,
          created_at timestamp NOT NULL DEFAULT now(),
          PRIMARY KEY (id),
          UNIQUE (subdivision_key, block, lot)
        )
      `);
    } else {
      await db.query(`
        CREATE TABLE IF NOT EXISTS subdivision_lots (
          id INT(11) NOT NULL AUTO_INCREMENT,
          subdivision_key VARCHAR(150) NOT NULL,
          block VARCHAR(30) NOT NULL DEFAULT '',
          lot VARCHAR(30) NOT NULL DEFAULT '',
          latitude DOUBLE NOT NULL,
          longitude DOUBLE NOT NULL,
          created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
          PRIMARY KEY (id),
          UNIQUE KEY uk_subdivision_lots_blk_lot (subdivision_key, block, lot)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
      `);
    }
    console.log("✅ subdivision_lots table verified.");
    return true;
  } catch (error) {
    console.warn("⚠️ Failed to ensure subdivision_lots table:", error.message);
    return false;
  }
}

module.exports = { ensureSubdivisionLots };
